const items = $input.all();
const content = items[0].json.message.content;

let analyses;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  analyses = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  analyses = [];
}

// Rank by relevance score
analyses.sort((a, b) => (b.relevance || 0) - (a.relevance || 0));

return [{
  json: {
    query: $('Webhook').item.json.body.query,
    totalResults: analyses.length,
    highlyRelevant: analyses.filter(a => a.relevance >= 7).length,
    rankedResults: analyses,
    searchDate: new Date().toISOString()
  }
}];

parameters.message:
